CREATE TABLE IF NOT EXISTS trade (id INT AUTO_INCREMENT PRIMARY KEY, ticker VARCHAR(12) NOT NULL, `date` DATE NOT NULL, venue VARCHAR(20) NOT NULL, quantity DECIMAL(18, 6) NOT NULL, unit_price DECIMAL(18, 6) NOT NULL, institution_id INT NOT NULL, fee DECIMAL(18, 6) NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_trade_institution_id__id FOREIGN KEY (institution_id) REFERENCES institution(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS import (id INT AUTO_INCREMENT PRIMARY KEY, `source` VARCHAR(20) NOT NULL, file_name VARCHAR(255) NOT NULL, file_hash VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL);
ALTER TABLE import ADD CONSTRAINT import_file_hash_unique UNIQUE (file_hash);
CREATE TABLE IF NOT EXISTS import_row (id INT AUTO_INCREMENT PRIMARY KEY, import_id INT NOT NULL, `date` DATE NOT NULL, side VARCHAR(4) NOT NULL, venue VARCHAR(20) NOT NULL, ticker VARCHAR(12) NOT NULL, quantity DECIMAL(18, 6) NOT NULL, unit_price DECIMAL(18, 6) NOT NULL, institution_name VARCHAR(100) NOT NULL, error VARCHAR(255) NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_import_row_import_id__id FOREIGN KEY (import_id) REFERENCES import(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
